import{_ as o,o as a,c as t,ag as r}from"./chunks/framework.D9kpkP22.js";const g=JSON.parse('{"title":"IcedSpear","description":"","frontmatter":{},"headers":[],"relativePath":"icedspear/index.md","filePath":"icedspear/index.md"}'),n={name:"icedspear/index.md"};function i(d,e,s,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="icedspear" tabindex="-1">IcedSpear <a class="header-anchor" href="#icedspear" aria-label="Permalink to &quot;IcedSpear&quot;">​</a></h1><p>IcedSpear is the core plugin for FragMC, providing essential lobby and game management features for <strong>Paper 26.2</strong> <code>26.2.build.123-stable</code> <code>Java 25</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>IcedSpear handles the core logic for:</p><ul><li><strong>Map Management</strong>: Dynamic instance creation and lifecycle handling with <code>FastAsyncWorldEdit</code> <code>2.11.1</code> and <code>12h</code> cache.</li><li><strong>Party System</strong>: Robust party management for group play.</li><li><strong>Social Features</strong>: Friend lists and social interactions.</li><li><strong>Competition</strong>: Global and per-map leaderboards.</li><li><strong>Bedrock Crossplay</strong>: Via <code>Geyser 2.2.0+</code> + <code>Floodgate 2.2.0+</code> <code>softdepend</code>.</li></ul><p>Now <code>2.0.10-alpha</code> with <strong>Blocks</strong> <code>Smart zone blocks</code> and <strong>Editor</strong> <code>lightweight Dropbox + Multiverse</code> addons (<code>IcedSpear/Addons/Blocks</code> <code>Editor</code> <code>2.0.10-alpha</code>).</p><p>It is designed to be extensible via the <a href="./api/">API</a>, allowing developers to create custom game modes and integrations.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>Explore the detailed documentation for IcedSpear:</p><ul><li><a href="./features.html"><strong>Features</strong></a>: In-depth look at maps, parties, and friends.</li><li><a href="./commands.html"><strong>Commands &amp; Permissions</strong></a>: Full list of commands and permission nodes.</li><li><a href="./configuration.html"><strong>Configuration</strong></a>: Guide to <code>config.yml</code> and map setup.</li><li><a href="./mechanics.html"><strong>Mechanics</strong></a>: Details on map lifecycle, special blocks, and timers.</li></ul>',10)])])}const h=o(n,[["render",i]]);export{g as __pageData,h as default};
